<script lang="ts">
  let { alert, clip, loading = false, error = '', onClose, formatDate, duration, labelClass, statusLabel } = $props<any>();
</script>

<div class="modal-overlay" role="presentation" onclick={(event) => { if (event.target === event.currentTarget) onClose(); }}>
  <div class="dialog" role="dialog" aria-modal="true" aria-labelledby="event-detail-title"><div class="dialog-top"><div><div class="eyebrow">EVIDENCIA DEL EVENTO</div><h2 id="event-detail-title">{labelClass(alert.clase)}</h2><p>{alert.camera ?? 'Cámara no identificada'} · {formatDate(alert.timestamp_inicio ?? alert.fecha_hora)}</p></div><button class="close" type="button" aria-label="Cerrar detalle del evento" onclick={onClose}>×</button></div><div class="clip-panel" aria-live="polite">{#if loading}<div>Consultando evidencia…</div>{:else if clip?.status === 'recording'}<div>● Grabando…</div>{:else if clip?.url}<video controls preload="metadata" src={clip.url}><track kind="captions" /></video>{:else}<div>{statusLabel(clip?.status)}: no hay un clip disponible todavía.</div>{/if}</div>{#if error}<p class="error">No se pudo consultar el clip: {error}</p>{/if}<dl><div><dt>Inicio</dt><dd>{formatDate(alert.timestamp_inicio ?? alert.fecha_hora)}</dd></div><div><dt>Fin (liberación VadCLIP)</dt><dd>{formatDate(alert.timestamp_fin ?? alert.fecha_hora_fin)}</dd></div><div><dt>Duración</dt><dd>{duration(alert.duracion_segundos ?? clip?.duration_seconds)}</dd></div><div><dt>Estado</dt><dd>{statusLabel(alert.status)}</dd></div><div><dt>Anomalía VadCLIP</dt><dd>{alert.confianza == null ? '—' : `${(Number(alert.confianza) * 100).toFixed(1)}%`}</dd></div><div><dt>Umbral de apertura</dt><dd>{alert.threshold == null ? '—' : `${(Number(alert.threshold) * 100).toFixed(1)}%`}</dd></div></dl></div>
</div>

<style>.modal-overlay{position:fixed;inset:0;background:#0b1c32a8;display:flex;justify-content:center;align-items:center;padding:18px;z-index:50}.dialog{background:#fff;width:100%;max-width:690px;border-radius:12px;padding:28px;max-height:95vh;overflow:auto}.dialog-top{display:flex;justify-content:space-between;gap:15px}.dialog h2{margin:8px 0;font-size:24px}.dialog p{color:#4a6178;font-size:12px}.close{border:0;background:none;font-size:28px}.clip-panel{background:#071a32;color:#dceafb;border-radius:8px;min-height:220px;display:grid;place-items:center;overflow:hidden;padding:20px;text-align:center}.clip-panel video{width:100%;max-height:390px}.error{color:#a3494d}dl{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:17px}dt{font-size:10px;color:#71879d;text-transform:uppercase}dd{margin:4px 0;font-size:13px}.eyebrow{color:#6991ae;font-size:10px;font-weight:800;letter-spacing:1.5px}</style>
